import{_ as n,a0 as d,w as r,s as p,ao as o,I as i,a1 as l,A as s,x as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"在 Fedora 下使用下拉式終端更快輸入命令 | LCTT x X-CMD","titleTemplate":false,"description":"在 Fedora 下使用下拉式終端更快輸入命令 | LCTT (201908) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Fedora 下使用下拉式終端更快輸入命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Fedora 下使用下拉式終端更快輸入命令 | LCTT (201908) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201908/20190809 Use a drop-down terminal for fast commands in Fedora","title":"在 Fedora 下使用下拉式終端更快輸入命令","tag":"201908","desc":""},"relativePath":"201908/20190809 Use a drop-down terminal for fast commands in Fedora.md","filePath":"[post].md"}'),g={name:"201908/20190809 Use a drop-down terminal for fast commands in Fedora.md"};function u(k,a,h,f,m,b){const t=d("Link");return r(),p("div",null,[a[28]||(a[28]=o('<h1 id="在-fedora-下使用下拉式終端更快輸入命令" tabindex="-1">在 Fedora 下使用下拉式終端更快輸入命令 <a class="header-anchor" href="#在-fedora-下使用下拉式終端更快輸入命令" aria-label="Permalink to “在 Fedora 下使用下拉式終端更快輸入命令”">​</a></h1><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/07/dropdown-terminals-816x345.jpg" alt=""></p><p>下拉式終端可以一鍵打開，並快速輸入桌面上的任何命令。通常它會以平滑的方式創建終端，有時會帶有下拉效果。本文演示瞭如何使用 Yakuake、Tilda、Guake 和 GNOME 擴展等下拉式終端來改善和加速日常任務。</p><h3 id="yakuake" tabindex="-1">Yakuake <a class="header-anchor" href="#yakuake" aria-label="Permalink to “Yakuake”">​</a></h3>',4)),i("p",null,[l(t,{href:"https://kde.org/applications/system/org.kde.yakuake"},{default:s(()=>[...a[0]||(a[0]=[e("Yakuake",-1)])]),_:1}),a[1]||(a[1]=e(" 是一個基於 KDE Konsole 技術的下拉式終端模擬器。它以 GNU GPLv2 條款分發。它包括以下功能：",-1))]),a[29]||(a[29]=o('<ul><li>從屏幕頂部平滑地滾下</li><li>標籤式界面</li><li>尺寸和動畫速度可配置</li><li>換膚</li><li>先進的 D-Bus 接口</li></ul><p>要安裝 Yakuake，請使用以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install -y yakuake</span></span></code></pre></div><h4 id="啓動和配置" tabindex="-1">啓動和配置 <a class="header-anchor" href="#啓動和配置" aria-label="Permalink to “啓動和配置”">​</a></h4><p>如果你運行 KDE，請打開系統設置，然後轉到“啓動和關閉”。將“yakuake”添加到“自動啓動”下的程序列表中，如下所示：</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/07/auto_start-1024x723.png" alt=""></p><p>Yakuake 運行時很容易配置，首先在命令列啓動該程序：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ yakuake &amp;</span></span></code></pre></div><p>隨後出現歡迎對話框。如果標準的快捷鍵和你已經使用的快捷鍵衝突，你可以設置一個新的。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/07/yakuake_config-1024x419.png" alt=""></p><p>點擊菜單按鈕，出現如下幫助菜單。接着，選擇“配置 Yakuake……”訪問配置選項。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/07/yakuake_config_01.png" alt=""></p><p>你可以自定義外觀選項，例如透明度、行為（例如當鼠標指針移過它們時聚焦終端）和窗口（如大小和動畫）。在窗口選項中，你會發現當你使用兩個或更多監視器時最有用的選項之一：“在鼠標所在的屏幕上打開”。</p><h4 id="使用-yakuake" tabindex="-1">使用 Yakuake <a class="header-anchor" href="#使用-yakuake" aria-label="Permalink to “使用 Yakuake”">​</a></h4><p>主要的快捷鍵有：</p><ul><li><code>F12</code> = 打開/撤回 Yakuake</li><li><code>Ctrl+F11</code> = 全屏模式</li><li><code>Ctrl+)</code> = 上下分割</li><li><code>Ctrl+(</code> = 左右分割</li><li><code>Ctrl+Shift+T</code> = 新會話</li><li><code>Shift+Right</code> = 下一個會話</li><li><code>Shift+Left</code> = 上一個會話</li><li><code>Ctrl+Alt+S</code> = 重命名會話</li></ul>',16)),i("p",null,[a[3]||(a[3]=e("以下是 Yakuake 像",-1)),l(t,{href:"https://fedoramagazine.org/4-cool-terminal-multiplexers/"},{default:s(()=>[...a[2]||(a[2]=[e("終端多路複用器",-1)])]),_:1}),a[4]||(a[4]=e("一樣分割會話的示例。使用此功能，你可以在一個會話中運行多個 shell。",-1))]),a[30]||(a[30]=i("p",null,[i("img",{src:"https://fedoramagazine.org/wp-content/uploads/2019/07/yakuake_usage.gif",alt:""})],-1)),a[31]||(a[31]=i("h3",{id:"tilda",tabindex:"-1"},[e("Tilda "),i("a",{class:"header-anchor",href:"#tilda","aria-label":"Permalink to “Tilda”"},"​")],-1)),i("p",null,[l(t,{href:"https://github.com/lanoxx/tilda"},{default:s(()=>[...a[5]||(a[5]=[e("Tilda",-1)])]),_:1}),a[6]||(a[6]=e(" 是一個下拉式終端，可與其他流行的終端模擬器相媲美，如 GNOME 終端、KDE 的 Konsole、xterm 等等。",-1))]),a[32]||(a[32]=o('<p>它具有高度可配置的界面。你甚至可以更改終端大小和動畫速度等選項。Tilda 還允許你啓用熱鍵，以綁定到各種命令和操作。</p><p>要安裝 Tilda，請運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install -y tilda</span></span></code></pre></div><h4 id="啓動和配置-1" tabindex="-1">啓動和配置 <a class="header-anchor" href="#啓動和配置-1" aria-label="Permalink to “啓動和配置”">​</a></h4><p>大多數用户更喜歡在登錄時就在後台運行一個下拉式終端。要設置此選項，請首先轉到桌面上的應用啓動器，搜索 Tilda，然後將其打開。</p><p>接下來，打開 Tilda 配置窗口。 選擇“隱藏啓動 Tilda”，即啓動時不會立即顯示終端。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/07/tilda_startup.png" alt=""></p><p>接下來，你要設置你的桌面自動啓動 Tilda。如果你使用的是 KDE，請轉到“系統設置 &gt; 啓動與關閉 &gt; 自動啓動”並“添加一個程序”。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/07/tilda_startup_alt.png" alt=""></p><p>如果你正在使用 GNOME，則可以在終端中運行此命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ln -s /usr/share/applications/tilda.desktop ~/.config/autostart/</span></span></code></pre></div><p>當你第一次運行它時，會出現一個嚮導來設置首選項。如果需要更改設置，請右鍵單擊終端並轉到菜單中的“首選項”。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/07/tilda_config.png" alt=""></p><p>你還可以創建多個配置文件，並綁定其他快捷鍵以在屏幕上的不同位置打開新終端。為此，請運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tilda -C</span></span></code></pre></div><p>每次使用上述命令時，Tilda 都會在名為 <code>~/.config/tilda/</code> 文件夾中創建名為 <code>config_0</code>、<code>config_1</code> 之類的新配置文件。然後，你可以映射組合鍵以打開具有一組特定選項的新 Tilda 終端。</p><h4 id="使用-tilda" tabindex="-1">使用 Tilda <a class="header-anchor" href="#使用-tilda" aria-label="Permalink to “使用 Tilda”">​</a></h4><p>主要快捷鍵有：</p><ul><li><code>F1</code> = 拉下終端 Tilda（注意：如果你有多個配置文件，快捷方式是 F1、F2、F3 等）</li><li><code>F11</code> = 全屏模式</li><li><code>F12</code> = 切換透明模式</li><li><code>Ctrl+Shift+T</code> = 添加標籤</li><li><code>Ctrl+Page Up</code> = 下一個標籤</li><li><code>Ctrl+Page Down</code> = 上一個標籤</li></ul><h3 id="gnome-擴展" tabindex="-1">GNOME 擴展 <a class="header-anchor" href="#gnome-擴展" aria-label="Permalink to “GNOME 擴展”">​</a></h3>',20)),i("p",null,[a[8]||(a[8]=e("Drop-down Terminal ",-1)),l(t,{href:"https://extensions.gnome.org/extension/442/drop-down-terminal/"},{default:s(()=>[...a[7]||(a[7]=[e("GNOME 擴展",-1)])]),_:1}),a[9]||(a[9]=e("允許你在 GNOME Shell 中使用這個有用的工具。它易於安裝和配置，使你可以快速訪問終端會話。",-1))]),a[33]||(a[33]=i("h4",{id:"安裝",tabindex:"-1"},[e("安裝 "),i("a",{class:"header-anchor",href:"#安裝","aria-label":"Permalink to “安裝”"},"​")],-1)),i("p",null,[a[11]||(a[11]=e("打開瀏覽器並轉到",-1)),l(t,{href:"https://extensions.gnome.org/extension/442/drop-down-terminal/"},{default:s(()=>[...a[10]||(a[10]=[e("此 GNOME 擴展的站點",-1)])]),_:1}),a[12]||(a[12]=e("。啓用擴展設置為“On”，如下所示：",-1))]),a[34]||(a[34]=o('<p><img src="https://fedoramagazine.org/wp-content/uploads/2019/07/gnome-shell-install_2-1024x455.png" alt=""></p><p>然後選擇“Install”以在系統上安裝擴展。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/07/gnome-shell-install_3.png" alt=""></p><p>執行此操作後，無需設置任何自動啓動選項。只要你登錄 GNOME，擴展程序就會自動運行！</p><h4 id="配置" tabindex="-1">配置 <a class="header-anchor" href="#配置" aria-label="Permalink to “配置”">​</a></h4><p>安裝後，將打開 Drop-down Terminal 配置窗口以設置首選項。例如，可以設置終端大小、動畫、透明度和使用滾動條。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/07/gnome-shell-install_4.png" alt=""></p><p>如果你將來需要更改某些首選項，請運行 <code>gnome-shell-extension-prefs</code> 命令並選擇“Drop Down Terminal”。</p><h4 id="使用該擴展" tabindex="-1">使用該擴展 <a class="header-anchor" href="#使用該擴展" aria-label="Permalink to “使用該擴展”">​</a></h4><p>快捷鍵很簡單：</p><ul><li>反尖號 （通常是 <code>Tab</code> 鍵上面的一個鍵) = 打開/撤回終端</li><li><code>F12</code> （可以定製） = 打開/撤回終端</li></ul><hr>',12)),i("p",null,[a[14]||(a[14]=e("via: ",-1)),l(t,{href:"https://fedoramagazine.org/use-a-drop-down-terminal-for-fast-commands-in-fedora/"},{default:s(()=>[...a[13]||(a[13]=[e("https://fedoramagazine.org/use-a-drop-down-terminal-for-fast-commands-in-fedora/",-1)])]),_:1})]),i("p",null,[a[19]||(a[19]=e("作者：",-1)),l(t,{href:"https://fedoramagazine.org/author/schelp/"},{default:s(()=>[...a[15]||(a[15]=[e("Guilherme Schelp",-1)])]),_:1}),a[20]||(a[20]=e(" 選題：",-1)),l(t,{href:"https://github.com/lujun9972"},{default:s(()=>[...a[16]||(a[16]=[e("lujun9972",-1)])]),_:1}),a[21]||(a[21]=e(" 譯者：",-1)),l(t,{href:"https://github.com/wxy"},{default:s(()=>[...a[17]||(a[17]=[e("wxy",-1)])]),_:1}),a[22]||(a[22]=e(" 校對：",-1)),l(t,{href:"https://github.com/wxy"},{default:s(()=>[...a[18]||(a[18]=[e("wxy",-1)])]),_:1})]),i("p",null,[a[25]||(a[25]=e("本文由 ",-1)),l(t,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...a[23]||(a[23]=[e("LCTT",-1)])]),_:1}),a[26]||(a[26]=e(" 原創編譯，",-1)),l(t,{href:"https://linux.cn/"},{default:s(()=>[...a[24]||(a[24]=[e("Linux中國",-1)])]),_:1}),a[27]||(a[27]=e(" 榮譽推出",-1))])])}const c=n(g,[["render",u]]);export{C as __pageData,c as default};
